// A synchronous stand-in for a Worker. The 'worker side' squares numbers.
// It echoes back the SAME id it received — your job is the MAIN-side correlation.
function makeWorker() {
  let onMessage = null;
  return {
    set onmessage(fn) { onMessage = fn; },
    // main -> worker; worker replies synchronously via onMessage
    postMessage(msg) {
      const reply = { id: msg.id, result: msg.payload * msg.payload };
      onMessage({ data: reply });
    },
  };
}

